-- Synthetic metadata/authority fixture. Document metadata is not uploaded-byte or signature proof.
begin;
create extension if not exists pgtap with schema extensions;select extensions.no_plan();
insert into auth.users(id,email) values('eb100000-0000-4000-8000-000000000001','agreement-owner@local.invalid'),('eb100000-0000-4000-8000-000000000002','agreement-office@local.invalid'),('eb100000-0000-4000-8000-000000000003','agreement-employee@local.invalid'),('eb100000-0000-4000-8000-000000000004','agreement-other@local.invalid');
insert into public.companies(id,name) values('eb200000-0000-4000-8000-000000000001','Agreement Test Contractor'),('eb200000-0000-4000-8000-000000000002','Other Agreement Contractor');
insert into public.profiles(id,company_id,role,full_name) values('eb100000-0000-4000-8000-000000000001','eb200000-0000-4000-8000-000000000001','owner','Test Owner'),('eb100000-0000-4000-8000-000000000002','eb200000-0000-4000-8000-000000000001','office','Test Office'),('eb100000-0000-4000-8000-000000000003','eb200000-0000-4000-8000-000000000001','employee','Test Employee'),('eb100000-0000-4000-8000-000000000004','eb200000-0000-4000-8000-000000000002','owner','Other Owner');
insert into public.projects(id,company_id,job_number,name,status) values('eb500000-0000-4000-8000-000000000001','eb200000-0000-4000-8000-000000000001','LOCAL-NOT-EXTERNAL','Separate synthetic project','active');
create temp table agreement_test_context(key text primary key,value text);grant all on agreement_test_context to authenticated;
create function pg_temp.agreement_payload(p_action text default 'verify',p_previous uuid default null) returns jsonb language sql as $$select jsonb_build_object('project_id',(select value::uuid from agreement_test_context where key='project'),'expected_event_id',p_previous,'action',p_action,'evidence_basis',case when p_action='verify' then 'owner_attestation_copy_pending' else null end,'agreement_amount','25000.00','agreement_reference','LOCAL-SIGNED-AG','note','Synthetic owner evidence; executed copy is pending.','acknowledged',true);$$;
select set_config('request.jwt.claim.sub','eb100000-0000-4000-8000-000000000001',true);set local role authenticated;
insert into agreement_test_context select 'project',public.carez_intake_external_job('eb300000-0000-4000-8000-000000000001','{"job_number":"LOCAL-VERIFY-1","name":"Synthetic external job","customer_name":"Synthetic General Contractor","agreement_reference":"LOCAL-SIGNED-AG","agreement_evidence":"reported_signed_no_executed_copy","agreement_amount":25000,"external_proposal_amount":25000.12,"provisional_change_amount":800,"state":"WA"}')::text;
select extensions.is((select agreement_captured from public.project_job_readiness_summary where project_id=(select value::uuid from agreement_test_context where key='project')),false,'external intake starts with agreement hold');
select extensions.throws_like($$select public.carez_verify_external_agreement(gen_random_uuid(),pg_temp.agreement_payload()||'{"agreement_amount":"25000.12"}')$$,'%amount or reference changed%','proposal cents cannot replace recorded agreement');
select extensions.throws_like($$select public.carez_verify_external_agreement(gen_random_uuid(),pg_temp.agreement_payload()||'{"acknowledged":false}')$$,'%Explicit owner verification%','verification requires explicit attestation');
select extensions.throws_like($$select public.carez_verify_external_agreement(gen_random_uuid(),pg_temp.agreement_payload()||'{"evidence_basis":"executed_copy_reviewed","document_id":"eb900000-0000-4000-8000-000000000001"}')$$,'%Retained agreement evidence%','unavailable document cannot be called reviewed');
insert into agreement_test_context select 'verified',public.carez_verify_external_agreement('eb400000-0000-4000-8000-000000000001',pg_temp.agreement_payload())::text;
select extensions.is((select evidence_basis from public.external_agreement_verifications where id=(select value::uuid from agreement_test_context where key='verified')),'owner_attestation_copy_pending','copy pending remains explicit after owner verification');
select extensions.is((select original_contract_value from public.project_award_records where project_id=(select value::uuid from agreement_test_context where key='project')),25000::numeric,'operational agreement keeps original amount');
select extensions.is((select agreement_captured from public.project_job_readiness_summary where project_id=(select value::uuid from agreement_test_context where key='project')),true,'governed owner verification clears only agreement check');
select extensions.is((select job_ready from public.project_job_readiness_summary where project_id=(select value::uuid from agreement_test_context where key='project')),false,'unresolved tax and other setup holds still apply');
select extensions.is((select has_awarded_budget from public.project_startup_readiness where project_id=(select value::uuid from agreement_test_context where key='project')),false,'external agreement does not claim frozen estimate baseline');
select extensions.is((select count(*)::integer from public.commercial_baselines where project_id=(select value::uuid from agreement_test_context where key='project')),0,'no commercial baseline fabricated');
select extensions.is((select count(*)::integer from public.award_decisions where project_id=(select value::uuid from agreement_test_context where key='project')),0,'no internal Award fabricated');
select extensions.is((select count(*)::integer from public.project_authorized_contract_summary where project_id=(select value::uuid from agreement_test_context where key='project')),0,'accepted-baseline financial authority remains absent');
select extensions.is((select external_proposal_amount-supplied_agreement_amount from public.project_external_intakes where project_id=(select value::uuid from agreement_test_context where key='project')),0.12::numeric,'proposal discrepancy preserved');
select extensions.is((select provisional_change_amount from public.project_external_intakes where project_id=(select value::uuid from agreement_test_context where key='project')),800::numeric,'provisional change remains separate');
select extensions.is(public.carez_verify_external_agreement('eb400000-0000-4000-8000-000000000001',pg_temp.agreement_payload())::text,(select value from agreement_test_context where key='verified'),'retry returns the same verification');
select extensions.throws_like($$select public.carez_verify_external_agreement('eb400000-0000-4000-8000-000000000001',pg_temp.agreement_payload()||'{"note":"Different later source claim"}')$$,'%different verification evidence%','request identity prevents changed evidence');
select extensions.throws_like($$select public.carez_verify_external_agreement(gen_random_uuid(),pg_temp.agreement_payload())$$,'%evidence changed%','stale verification context cannot override newer evidence');
select extensions.throws_like($$update public.project_award_records set original_contract_value=25800 where project_id=(select value::uuid from agreement_test_context where key='project')$$,'%governed owner verification%','direct DML cannot add provisional amount to agreement');
select extensions.throws_like($$update public.external_agreement_verifications set note='rewrite'$$,'%permission denied%','app role cannot rewrite verification history');
select set_config('request.jwt.claim.sub','eb100000-0000-4000-8000-000000000002',true);
select extensions.throws_like($$update public.project_award_records set accepted_email='fabricated@local.invalid' where project_id=(select value::uuid from agreement_test_context where key='project')$$,'%cannot fabricate customer acceptance%','office cannot fabricate customer acceptance attribution');
select extensions.throws_like($$update public.project_award_records set authorization_text='Customer signed in app' where project_id=(select value::uuid from agreement_test_context where key='project')$$,'%cannot fabricate customer acceptance%','office cannot rewrite external verification meaning');
select extensions.throws_like($$update public.project_award_records set project_id='eb500000-0000-4000-8000-000000000001' where project_id=(select value::uuid from agreement_test_context where key='project')$$,'%identity cannot be moved%','office cannot retarget external agreement authority');
select extensions.throws_like($$insert into public.project_award_records(company_id,project_id,agreement_number,original_contract_value,external_verification_id) values(public.get_my_company_id(),'eb500000-0000-4000-8000-000000000001','LOCAL-SIGNED-AG',25000,(select value::uuid from agreement_test_context where key='verified'))$$,'%cannot authorize another project%','external verification cannot be copied to a nonexternal project');
select extensions.throws_like($$select public.carez_verify_external_agreement(gen_random_uuid(),pg_temp.agreement_payload('revoke',(select value::uuid from agreement_test_context where key='verified')))$$,'%Only the company owner%','office cannot impersonate owner verification');
select set_config('request.jwt.claim.sub','eb100000-0000-4000-8000-000000000004',true);
select extensions.is((select count(*)::integer from public.external_agreement_verifications where project_id=(select value::uuid from agreement_test_context where key='project')),0,'foreign company cannot read verification evidence');
select extensions.throws_like($$select public.carez_verify_external_agreement(gen_random_uuid(),pg_temp.agreement_payload())$$,'%Project unavailable%','foreign owner cannot verify another company job');
select set_config('request.jwt.claim.sub','eb100000-0000-4000-8000-000000000003',true);
select extensions.throws_like($$select public.carez_verify_external_agreement(gen_random_uuid(),pg_temp.agreement_payload())$$,'%Only the company owner%','employee cannot verify');
select set_config('request.jwt.claim.sub','eb100000-0000-4000-8000-000000000001',true);
insert into agreement_test_context select 'revoked',public.carez_verify_external_agreement('eb400000-0000-4000-8000-000000000002',pg_temp.agreement_payload('revoke',(select value::uuid from agreement_test_context where key='verified')))::text;
select extensions.is((select status from public.project_award_records where project_id=(select value::uuid from agreement_test_context where key='project')),'void','revocation retains the operational record');
select extensions.is((select agreement_captured from public.project_job_readiness_summary where project_id=(select value::uuid from agreement_test_context where key='project')),false,'revocation restores agreement hold');
select extensions.is((select count(*)::integer from public.external_agreement_verifications where project_id=(select value::uuid from agreement_test_context where key='project')),2,'verify and revoke events both retained');
select extensions.is((select has_awarded_budget from public.project_startup_readiness where project_id=(select value::uuid from agreement_test_context where key='project')),false,'revocation does not invent or remove an internal baseline');
select extensions.throws_like($$update public.project_award_records set status='accepted' where project_id=(select value::uuid from agreement_test_context where key='project')$$,'%status must match%','direct DML cannot reactivate revoked agreement');
reset role;set local role anon;
select extensions.throws_like($$select public.carez_verify_external_agreement(gen_random_uuid(),'{}')$$,'%permission denied%','anonymous cannot verify');
reset role;select * from extensions.finish();rollback;
